import {validateItems,totals,vatBase,validatePODate} from './domain.js';

const allowedRoles=new Set(['owner','office','primary']);
const jsonClone=value=>JSON.parse(JSON.stringify(value));
const fingerprint=value=>JSON.stringify(value,Object.keys(value||{}).sort());
const requiredReason=value=>{const reason=String(value||'').trim();if(!reason)throw Error('ระบุเหตุผลก่อนทำรายการ');if(reason.length>2000)throw Error('เหตุผลต้องไม่เกิน 2,000 ตัวอักษร');return reason;};
const totalFor=items=>items.reduce((sum,item)=>sum+item.total_cents,0);
export const itemStatusLabels={pending:'รออนุมัติ',returned:'ส่งกลับแก้ไข',rejected:'ไม่อนุมัติ',budget_approved:'อนุมัติวงเงินประมาณการ',approved:'อนุมัติซื้อ',revision_requested:'ขอแก้ไข · พักอนุมัติ',editing:'กำลังแก้ไข',received:'รับสินค้าแล้ว'};
export const priceKindLabels={confirmed:'ราคายืนยัน',estimated:'ราคาประมาณการ'};
const authorFields=['department','name','spec','source','note','payment_method','qty','unit','unit_price','vat'];
export function itemSnapshot(item){const fields=Object.fromEntries(authorFields.map(key=>[key,item[key]]));return jsonClone({id:item.id,revision:item.revision,price_kind:item.price_kind||'confirmed',...fields,...Object.fromEntries(['base_cents','tax_cents','total_cents'].map(key=>[key,item[key]]))});}
function validateAuthorFields(item){if(!String(item.department||'').trim())throw Error('ระบุแผนกหรือสาขาของรายการ');if(!String(item.unit||'').trim())throw Error('ระบุหน่วยของรายการ');if(!['credit','cash'].includes(item.payment_method))throw Error('เลือกการชำระเงินเป็นเครดิตหรือเงินสด');if(!['confirmed','estimated'].includes(item.price_kind))throw Error('เลือกว่าราคาเป็นราคายืนยันหรือราคาประมาณการ');}
export function withItemTotals(item){validateAuthorFields(item);const [validated]=validateItems([item]);return {...validated,id:item.id,state:item.state||'pending',price_kind:item.price_kind||'confirmed',revision:item.revision||1};}
export const isConfirmedPurchase=item=>['approved','received'].includes(item.state)&&item.price_kind==='confirmed';
export function deriveFinancials(po){const items=po.items||[],eligible=items.filter(isConfirmedPurchase),budget=items.filter(i=>i.state==='budget_approved');return {...totals(items),vat_base_cents:vatBase(items),submitted_total_cents:totalFor(items),budget_authorized_cents:totalFor(budget),confirmed_purchase_cents:totalFor(eligible),received_cents:totalFor(items.filter(i=>i.state==='received'&&i.price_kind==='confirmed')),rejected_cents:totalFor(items.filter(i=>i.state==='rejected')),active_confirmed_cents:totalFor(eligible)};}
export function derivePOStatus(items,closed=false){if(closed)return 'closed';const live=items.filter(i=>i.state!=='rejected');if(!live.length)return 'rejected';if(live.every(i=>i.state==='received'))return 'received';if(live.some(i=>i.state==='revision_requested'||i.state==='editing'))return 'revision_requested';if(live.some(i=>i.state==='pending'||i.state==='returned'))return 'pending';if(live.some(i=>i.state==='budget_approved'))return 'budget_approved';if(live.every(i=>['approved','received'].includes(i.state)))return 'approved';return 'mixed';}
function refreshPO(po){po.status=derivePOStatus(po.items,po.closed_at!=null);Object.assign(po,deriveFinancials(po));return po;}
function assertActor(actor){if(!actor||!allowedRoles.has(actor.role))throw Error('บัญชีนี้ไม่มีสิทธิ์ทำรายการ');}
function canAccess(po,actor){if(actor.role==='owner'||actor.role==='primary')return true;return po.created_by===actor.id;}
function canAuthor(po,actor){return ['office','primary'].includes(actor.role)&&po.created_by===actor.id;}
function appendEvent(po,item,action,actor,reason='',extra={}){const event={id:crypto.randomUUID(),item_id:item?.id||null,item_name:item?.name||null,action,actor_id:actor.id,actor_name:actor.display_name,at:new Date().toISOString(),reason:reason||'',revision:item?.revision||null,...extra};po.events.push(event);}
function editAudit(po,item,before,actor,reason=''){const after=itemSnapshot(item),oldAmount=before.total_cents,newAmount=item.total_cents;appendEvent(po,item,'edit',actor,reason,{before,after,old_amount_cents:oldAmount,new_amount_cents:newAmount,delta_cents:newAmount-oldAmount});}
function checkTransition(item,action,actor){const states={approve:['owner','pending'],approve_estimate:['owner','pending'],return:['owner','pending'],return_edit:['owner','pending','approved','budget_approved'],reject:['owner','pending'],confirm_price:['office','budget_approved'],resubmit:['office','returned'],request_revision:['office','approved','budget_approved'],unlock:['owner','revision_requested'],refuse_revision:['owner','revision_requested'],submit_revision:['office','editing'],receive:['office','approved']};const rule=states[action];const allowed=rule&&((rule[0]==='office'&&['office','primary'].includes(actor.role))||actor.role===rule?.[0]);if(!allowed||!rule.slice(1).includes(item.state))throw Error('สถานะเปลี่ยนแล้วหรือบัญชีนี้ไม่มีสิทธิ์ทำรายการ');if(action==='approve'&&item.price_kind!=='confirmed')throw Error('ราคาประมาณการต้องยืนยันและส่งอนุมัติใหม่ก่อน');if(action==='approve_estimate'&&item.price_kind!=='estimated')throw Error('อนุมัติวงเงินประมาณการใช้ได้เฉพาะราคาประมาณการ');if(action==='receive'&&item.price_kind!=='confirmed')throw Error('ราคาประมาณการต้องยืนยันและได้รับอนุมัติก่อนรับสินค้า');}
function mutate(po,item,action,actor,reason,extra={}){const prev=item.state;switch(action){case 'approve':item.state='approved';item.approved_snapshot=itemSnapshot(item);break;case 'approve_estimate':item.state='budget_approved';item.price_kind='estimated';item.budget_snapshot=itemSnapshot(item);break;case 'return':item.state='returned';item.return_reason=reason;break;case 'return_edit':item.state='editing';item.paused_from=prev;item.return_reason=reason;item.revision_reason=reason;break;case 'reject':item.state='rejected';item.reject_reason=reason;break;case 'confirm_price':item.state='pending';item.price_kind='confirmed';item.confirmed_at=new Date().toISOString();break;case 'resubmit':item.state='pending';item.return_reason='';break;case 'request_revision':item.state='revision_requested';item.paused_from=prev;item.revision_reason=reason;break;case 'unlock':item.state='editing';item.revision_reason='';break;case 'refuse_revision':item.state=item.paused_from;item.revision_reason='';item.paused_from=null;break;case 'submit_revision':item.state='pending';item.paused_from=null;break;case 'receive':item.state='received';item.received_at=new Date().toISOString();break;default:throw Error('ไม่รองรับการทำรายการนี้');}item.revision++;appendEvent(po,item,action,actor,reason,extra);}
function updateItem(po,itemId,fields,actor,reason=''){assertActor(actor);if(!canAuthor(po,actor))throw Error('แก้ไขได้เฉพาะใบ PO ของผู้สร้าง');if(po.closed_at)throw Error('ใบ PO ปิดแล้ว แก้ไขไม่ได้');const item=po.items.find(row=>row.id===itemId);if(!item||!['returned','editing','budget_approved'].includes(item.state))throw Error('รายการนี้ยังไม่ได้รับอนุญาตให้แก้ไข');const before=itemSnapshot(item);const values=Object.fromEntries(authorFields.map(key=>[key,fields[key]??item[key]]));const next=withItemTotals({...values,id:item.id,state:item.state,price_kind:fields.price_kind??item.price_kind,revision:item.revision+1});Object.assign(item,next);editAudit(po,item,before,actor,reason);refreshPO(po);return po;}
function checkClose(po,confirmed){if(!confirmed)throw Error('ยืนยันว่าได้รับใบกำกับภาษีก่อนปิดใบ PO');const unresolved=po.items.filter(i=>!['received','rejected'].includes(i.state));if(unresolved.length)throw Error('ยังมีรายการที่ต้องดำเนินการ กรุณาแก้ไขให้ครบก่อนปิดใบ PO');if(!po.items.some(i=>i.state==='received'))throw Error('ใบ PO ที่ไม่เหลือรายการรับสินค้าให้ปิดได้');}

export function createPreviewService({storage,fixtures=[]}={}){
 const store=storage||globalThis.localStorage;const storageKey='po-grands-preview-workflow-v1';
 const read=()=>{try{return JSON.parse(store?.getItem(storageKey)||'null')}catch{return null}};
 const write=envelope=>{if(!store)throw Error('เบราว์เซอร์ไม่รองรับการเก็บข้อมูลทดลอง');store.setItem(storageKey,JSON.stringify(envelope));};
 const seed=()=>{const current=read();if(current&&Array.isArray(current.rows)&&current.commands)return current;const rows=jsonClone(fixtures).map(refreshPO),envelope={rows,commands:{}};write(envelope);return envelope;};
 const envelope=()=>seed();const getRows=()=>envelope().rows;const commands=()=>envelope().commands;
 function load(poId,actor){assertActor(actor);const po=getRows().find(row=>row.id===poId);if(!po||!canAccess(po,actor))throw Error('ไม่พบใบ PO หรือไม่มีสิทธิ์เข้าถึง');return jsonClone(po);}
 function run(poId,action,{actor,itemId,reason='',fields,confirmed=false,key,expectedVersion}={}){
   assertActor(actor);if(!key)throw Error('คำสั่งนี้ไม่มีรหัสป้องกันรายการซ้ำ');
   const whyText=String(reason||'');if(whyText.length>2000)throw Error('เหตุผลต้องไม่เกิน 2,000 ตัวอักษร');const cmd={poId,action,actorId:actor.id,actorRole:actor.role,itemId,reason:whyText,fields:fields?jsonClone(fields):null,confirmed};const fp=JSON.stringify(cmd);const cache=commands();
   const rows=getRows(),index=rows.findIndex(row=>row.id===poId),po=rows[index];if(!po||!canAccess(po,actor))throw Error('ไม่พบใบ PO หรือไม่มีสิทธิ์เข้าถึง');const ownerOnly=['approve','approve_estimate','return','return_edit','reject','unlock','refuse_revision','close'].includes(action),authorOnly=['confirm_price','resubmit','request_revision','submit_revision'].includes(action);if(ownerOnly&&actor.role!=='owner')throw Error('ทำรายการนี้ได้เฉพาะเจ้าของ');if(authorOnly&&!canAuthor(po,actor))throw Error('ทำรายการได้เฉพาะผู้สร้างใบ PO');if(action==='receive'&&(!['office','primary'].includes(actor.role)||(actor.role==='office'&&!canAuthor(po,actor))))throw Error('รับสินค้าได้เฉพาะใบ PO ที่มีสิทธิ์เข้าถึง');if(!ownerOnly&&!authorOnly&&action!=='receive'&&action!=='create'&&action!=='close')throw Error('ไม่รองรับการทำรายการนี้');if(action==='confirm_price'||action==='resubmit'||action==='submit_revision')throw Error('แก้ไขข้อมูลและส่งกลับขออนุมัติผ่านแบบฟอร์มแก้ไข');const cached=cache[key];if(cached){if(cached.fingerprint!==fp)throw Error('รหัสคำสั่งนี้ถูกใช้กับข้อมูลหรือบัญชีอื่นแล้ว');return jsonClone(cached.result);}if(expectedVersion!==po.version)throw Error('ข้อมูลเปลี่ยนแล้ว กรุณาโหลดรายการล่าสุดก่อนบันทึก');
   if(action==='create')throw Error('สร้างใบ PO ผ่าน create()');if(action==='close'){if(po.closed_at)throw Error('ใบ PO ปิดแล้ว');checkClose(po,confirmed);po.closed_at=new Date().toISOString();appendEvent(po,null,'close',actor,'');}
   else {if(po.closed_at)throw Error('ใบ PO ปิดแล้ว แก้ไขไม่ได้');const item=po.items.find(row=>row.id===itemId);if(!item)throw Error('ไม่พบรายการสินค้า');if(action==='receive'){if(confirmed!==true)throw Error('ยืนยันว่าได้รับสินค้ารายการนี้แล้ว');if(actor.role==='office'&&!canAuthor(po,actor)||!['office','primary'].includes(actor.role)||item.state!=='approved'||item.price_kind!=='confirmed')throw Error('รับสินค้าได้เฉพาะรายการที่อนุมัติแล้วและมีราคายืนยัน');}else checkTransition(item,action,actor);let why=whyText;if(['return','return_edit','reject','request_revision','refuse_revision'].includes(action))why=requiredReason(reason);
     if(action==='update')throw Error('ใช้ updateItem() เพื่อเก็บประวัติการแก้ไข');if(action==='edit_item')throw Error('การแก้ไขต้องอยู่ในรายการที่ปลดล็อก');mutate(po,item,action,actor,why);if(action==='resubmit'||action==='submit_revision'){const before=itemSnapshot(item);if(!fields)throw Error('แก้ไขข้อมูลรายการก่อนส่งอนุมัติอีกครั้ง');const revised=withItemTotals({...before,...fields,id:item.id,state:item.state,revision:item.revision});Object.assign(item,revised);item.state='pending';editAudit(po,item,before,actor,why);} }
   refreshPO(po);po.version++;rows[index]=po;const result=jsonClone(po);cache[key]={fingerprint:fp,result};write({rows,commands:cache});return result;
 }
 function create(items,{actor,poDate,poNumber,key,requester}={}){assertActor(actor);if(!['office','primary'].includes(actor.role))throw Error('เปิดใบ PO ได้เฉพาะพนักงาน');if(!key)throw Error('คำสั่งนี้ไม่มีรหัสป้องกันรายการซ้ำ');const source=validateItems(items);items.forEach(validateAuthorFields);const priceKinds=items.map(item=>item.price_kind||'confirmed'),date=validatePODate(poDate),cmd={actorId:actor.id,actorRole:actor.role,action:'create',poDate:date,items:source,priceKinds},fp=JSON.stringify(cmd),current=envelope(),cache=current.commands;if(cache[key]){if(cache[key].fingerprint!==fp)throw Error('รหัสคำสั่งนี้ถูกใช้กับข้อมูลหรือบัญชีอื่นแล้ว');return jsonClone(cache[key].result);}const validated=source.map((item,index)=>({...item,id:`${key}-item-${index+1}`,state:'pending',price_kind:priceKinds[index],revision:1}));const rows=current.rows;const po={id:`${key}-po`,po_number:poNumber||`DEMO-${new Date().getFullYear()}-${String(rows.length+1).padStart(5,'0')}`,po_date:date,created_at:new Date().toISOString(),created_by:actor.id,requester_name:requester||actor.display_name,version:1,closed_at:null,items:validated,events:[]};appendEvent(po,null,'create',actor);refreshPO(po);rows.unshift(po);const result=jsonClone(po);cache[key]={fingerprint:fp,result};write({rows,commands:cache});return result;}
 function edit(poId,itemId,fields,{actor,reason='',key,expectedVersion,submit=false}={}){assertActor(actor);if(!key)throw Error('คำสั่งนี้ไม่มีรหัสป้องกันรายการซ้ำ');const current=envelope(),cache=current.commands,cmd={poId,itemId,fields:jsonClone(fields),actorId:actor.id,actorRole:actor.role,action:'edit',reason,submit};const fp=JSON.stringify(cmd),rows=current.rows,index=rows.findIndex(row=>row.id===poId),po=rows[index];if(!po||!canAccess(po,actor))throw Error('ไม่พบใบ PO หรือไม่มีสิทธิ์เข้าถึง');if(!canAuthor(po,actor))throw Error('แก้ไขได้เฉพาะใบ PO ของผู้สร้าง');const cached=cache[key];if(cached){if(cached.fingerprint!==fp)throw Error('รหัสคำสั่งนี้ถูกใช้กับข้อมูลหรือบัญชีอื่นแล้ว');return jsonClone(cached.result);}if(expectedVersion!==po.version)throw Error('ข้อมูลเปลี่ยนแล้ว กรุณาโหลดรายการล่าสุดก่อนบันทึก');const itemBefore=po.items.find(row=>row.id===itemId);if(!itemBefore||po.closed_at||!['returned','editing','budget_approved'].includes(itemBefore.state))throw Error('รายการนี้ยังไม่ได้รับอนุญาตให้แก้ไข');if(itemBefore.state==='budget_approved'&&(!submit||fields.price_kind!=='confirmed'))throw Error('ยืนยันราคาสุดท้ายและส่งอนุมัติใหม่ก่อนบันทึก');const before=itemSnapshot(itemBefore),oldState=itemBefore.state,result=updateItem(po,itemId,fields,actor,reason),item=result.items.find(row=>row.id===itemId);if(submit){if(oldState==='budget_approved'){item.price_kind='confirmed';item.confirmed_at=new Date().toISOString();item.state='pending';}else{item.state='pending';item.paused_from=null;}item.return_reason='';appendEvent(result,item,'resubmit',actor,reason,{before,after:itemSnapshot(item),old_amount_cents:before.total_cents,new_amount_cents:item.total_cents,delta_cents:item.total_cents-before.total_cents});}result.version++;rows[index]=refreshPO(result);cache[key]={fingerprint:fp,result:jsonClone(result)};write({rows,commands:cache});return jsonClone(result);}
 function list(actor){assertActor(actor);return getRows().filter(po=>canAccess(po,actor)).map(jsonClone);}
 function report(month,actor){if(!actor||actor.role!=='primary')throw Error('ดูรายงานรวมได้เฉพาะฝ่ายจัดซื้อหลักในโหมดทดลอง');const rows=list(actor).filter(po=>po.po_date.startsWith(month));const eligible=rows.flatMap(po=>po.items.filter(isConfirmedPurchase).map(item=>({po,item})));return {month,rows,total_cents:eligible.reduce((n,x)=>n+x.item.total_cents,0),budget_authorized_cents:rows.reduce((n,po)=>n+po.items.filter(i=>i.state==='budget_approved').reduce((s,i)=>s+i.total_cents,0),0),ordered_count:eligible.length,pending_count:rows.reduce((n,po)=>n+po.items.filter(i=>['pending','returned','revision_requested','editing'].includes(i.state)).length,0),rejected_count:rows.reduce((n,po)=>n+po.items.filter(i=>i.state==='rejected').length,0),eligible};}
 return {load,list,run,create,edit,report,reset(){store?.removeItem(storageKey);return jsonClone(seed().rows);},storageKey};
}
